-- Batched pattern for large UPDATEs:
DO $$
DECLARE batch_rows INT;
BEGIN
  LOOP
    WITH chunk AS (
      SELECT ctid FROM propertyfields WHERE <condition> LIMIT 10000
    )
    UPDATE FROM propertyfields WHERE ctid IN (SELECT ctid FROM chunk);
    GET DIAGNOSTICS batch_rows = ROW_COUNT;
    EXIT WHEN batch_rows = 0;
  END LOOP;
END $$;

